package com.supermetroid.editor.headless

internal data class HeadlessBossBehaviorField(
    val key: String,
    val label: String,
    val snesAddress: Int,
    val defaultValue: Int,
    val category: String,
    val unit: String = "",
    val signed: Boolean = false,
    val hex: Boolean = false,
    val minValue: Int? = null,
    val maxValue: Int? = null,
    val writeSnesAddresses: List<Int> = listOf(snesAddress),
)

internal data class HeadlessBossBehaviorDefinition(
    val configType: String,
    val patchId: String,
    val name: String,
    val description: String,
    val fields: List<HeadlessBossBehaviorField>,
)

private fun headlessBossBehaviorField(
    key: String,
    label: String,
    snesAddress: Int,
    defaultValue: Int,
    category: String,
    unit: String = "",
    signed: Boolean = false,
    hex: Boolean = false,
    minValue: Int? = null,
    maxValue: Int? = null,
    additionalWriteAddresses: List<Int> = emptyList(),
): HeadlessBossBehaviorField =
    HeadlessBossBehaviorField(
        key = key,
        label = label,
        snesAddress = snesAddress,
        defaultValue = defaultValue,
        category = category,
        unit = unit,
        signed = signed,
        hex = hex,
        minValue = minValue,
        maxValue = maxValue,
        writeSnesAddresses = (listOf(snesAddress) + additionalWriteAddresses).distinct(),
    )

