internal val HEADLESS_BOSS_BEHAVIOR_BY_CONFIG_TYPE: Map<String, HeadlessBossBehaviorDefinition> =
    HEADLESS_BOSS_BEHAVIOR_DEFINITIONS.associateBy { it.configType }

internal val HEADLESS_BOSS_BEHAVIOR_CONFIG_TYPES: Set<String> = HEADLESS_BOSS_BEHAVIOR_BY_CONFIG_TYPE.keys

internal fun HeadlessBossBehaviorField.logicalDefaultValue(): Int = logicalValue(defaultValue)

internal fun HeadlessBossBehaviorField.logicalValue(storedValue: Int): Int {
    val word = storedValue and 0xFFFF
    return if (signed && word > 0x7FFF) word - 0x10000 else word
}

internal fun HeadlessBossBehaviorField.storedValue(logicalValue: Int): Int =
    if (signed && logicalValue < 0) logicalValue + 0x10000 else logicalValue

internal fun HeadlessBossBehaviorField.logicalMinValue(): Int =
    minValue ?: when {
        signed && unit in setOf("px/frame", "steps/frame") -> -255
        signed -> -32768
        else -> 0
    }

internal fun HeadlessBossBehaviorField.logicalMaxValue(): Int {
    val inferred = maxValue ?: when {
        hex -> 0xFFFF
        unit == "hp" -> 32767
        unit == "frames" -> 32767
        unit == "px" -> 4095
        unit == "missiles" -> 999
        unit == "damage" -> 9999
        unit in setOf("px/frame", "steps/frame") -> 255
        unit == "subpx/frame" -> 32767
        unit == "speed" -> 32767
        signed -> 32767
        else -> 0xFFFF
    }
    return maxOf(inferred, logicalDefaultValue())
}

internal fun coerceHeadlessBossBehaviorValue(field: HeadlessBossBehaviorField, storedValue: Int): Int {
    val logical = field.logicalValue(storedValue).coerceIn(field.logicalMinValue(), field.logicalMaxValue())
    return field.storedValue(logical).coerceIn(0, 0xFFFF)
}
